package com.crms.controller;import com.crms.entity.Student;import com.crms.repository.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;@RestController @RequestMapping("/api/students") public class StudentController{private final StudentRepository students;private final UserRepository users;public StudentController(StudentRepository s,UserRepository u){students=s;users=u;}@GetMapping @PreAuthorize("hasAnyRole('ADMIN','PLACEMENT_OFFICER')")public List<Student> all(){return students.findAll();}@GetMapping("/me")public Student me(Authentication a){return students.findByUserId(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId()).orElseThrow();}@PutMapping("/me")public Student update(@RequestBody Student input,Authentication a){var s=me(a);s.setPhone(input.getPhone());s.setDepartment(input.getDepartment());s.setBranch(input.getBranch());s.setSkills(input.getSkills());s.setCgpa(input.getCgpa());s.setGraduationYear(input.getGraduationYear());s.setBacklogs(input.getBacklogs());return students.save(s);}@PostMapping("/me/resume")public Map<String,String> resume(@RequestParam MultipartFile file,Authentication a)throws Exception{if(!Objects.equals(file.getContentType(),"application/pdf"))throw new IllegalArgumentException("Only PDF resumes are accepted");var dir=Paths.get(System.getenv().getOrDefault("FILE_STORAGE_PATH","uploads"));Files.createDirectories(dir);var name=UUID.randomUUID()+".pdf";Files.copy(file.getInputStream(),dir.resolve(name),StandardCopyOption.REPLACE_EXISTING);var s=me(a);s.setResumePath(name);students.save(s);return Map.of("message","Resume uploaded","file",name);}}
